(function(){'use strict';const api=window.sunSchedule2026,$=id=>document.getElementById(id);if(!api||!$('scRecord'))return;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Lima',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()).split('/').reverse().join('-');
function peruToday(){const parts=new Intl.DateTimeFormat('en-US',{timeZone:'America/Lima',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()),m=Object.fromEntries(parts.map(x=>[x.type,x.value]));return m.year+'-'+m.month+'-'+m.day;}
const fmt=s=>{const d=api.date(s);return d?d.toLocaleDateString('es-PE',{timeZone:'UTC',day:'2-digit',month:'2-digit',year:'numeric'}):'Sin fecha';};
const records=()=>typeof data!=='undefined'&&Array.isArray(data)?data:[];
const actualFields={queries:'Fin de consultas y observaciones',integration:'Integración de bases',elevationRequest:'Solicitud de elevación',elevationRegister:'Registro de elevación',definitive:'Integración definitiva OECE',offers:'Presentación de ofertas',award:'Notificación de buena pro',consent:'Registro efectivo del consentimiento',documents:'Presentación de requisitos',observation:'Notificación de observaciones',corrected:'Subsanación presentada',signature:'Contrato suscrito',appealFiled:'Apelación interpuesta',appealNotice:'Traslado de apelación',hearing:'Audiencia TCP',appealInfo:'Cierre de información adicional TCP'};
$('scActualFields').innerHTML=Object.entries(actualFields).map(([k,v])=>'<label>'+esc(v)+'<input type="date" min="2026-01-01" data-sc-actual="'+k+'"></label>').join('');
$('scInternalFields').innerHTML=api.templates['LP-CP ABREV.'].filter(r=>r.row<=28).map(r=>'<label>'+esc(r.label.split('\n')[0])+'<input type="number" min="1" max="365" value="'+r.days+'" data-sc-duration="'+r.row+'"><small>'+esc(r.owner)+' · '+esc(r.source)+'</small></label>').join('')+'<label>Absolución e integración de bases<input type="number" min="1" max="120" value="2" data-sc-duration="integration"></label><label>Calificación y evaluación de ofertas<input type="number" min="1" max="120" value="2" data-sc-duration="evaluation"></label>';
let result=null,choiceSignature='';
function populate(){const selected=$('scRecord').value;const rows=records();const sig=rows.map(r=>r.id+'|'+r.descripcion+'|'+r.procedimiento).join('\n');if(sig===choiceSignature)return;choiceSignature=sig;$('scRecord').innerHTML='<option value="">＋ Nueva contratación / consulta libre</option>'+rows.map(r=>'<option value="'+esc(r.id)+'">'+esc(r.descripcion)+' · '+esc(r.procedimiento||'Sin tipo registrado')+'</option>').join('');if(rows.some(r=>String(r.id)===selected))$('scRecord').value=selected;}
function config(){const actual=Object.fromEntries([...document.querySelectorAll('[data-sc-actual]')].filter(e=>e.value).map(e=>[e.dataset.scActual,e.value]));const durations=Object.fromEntries([...document.querySelectorAll('[data-sc-duration]')].map(e=>[e.dataset.scDuration,Number(e.value)]));return {type:$('scType').value,anchor:$('scAnchor').value,date:$('scDate').value,singleOffer:$('scSingle').value==='one',guarantee:$('scGuarantee').value==='yes',elevation:$('scElevation').value==='yes',prepObservations:$('scPrepObs').value==='yes',contractObservations:$('scContractObs').value==='yes',guaranteeExtension:$('scExtension').value==='yes',appeal:$('scAppeal').value,appealSubsanation:$('scAppealSub').value==='yes',appealInformation:$('scAppealInfo').value==='yes',place:$('scPlace').value,extra:$('scExtra').value.split(/[;,\s]+/).filter(Boolean),actual,durations};}
function render(){try{const cfg=config();for(const x of cfg.extra)if(!api.date(x))throw Error('Día no laborable inválido: '+x+'. Usa AAAA-MM-DD.');result=api.plan(cfg);const heading=esc($('scName').value.trim()||'Consulta de nueva contratación');let html='<div class="sc-outcome"><span>'+heading+'</span><strong>'+(result.signature?'Firma proyectada: '+fmt(result.signature):result.unsupported?'Procedimiento fuera del alcance de las plantillas':'Contrato pendiente del resultado de apelación')+'</strong><small>'+esc(api.types[result.type]||cfg.type)+' · Desde '+esc(api.stages[cfg.anchor])+' del '+fmt(cfg.date)+'.</small></div>';
if(!result.unsupported){let phase='';html+='<div class="sc-tablewrap"><table class="sc-table"><thead><tr><th>Actividad y responsable</th><th>Inicio / fecha base</th><th>Fecha final o límite</th><th>Plazo y carácter</th></tr></thead><tbody>';
for(const r of result.rows){if(r.phase!==phase){phase=r.phase;html+='<tr class="sc-phase"><th colspan="4">'+esc(phase)+'</th></tr>';}
html+='<tr><td><b>'+esc(r.label)+'</b>'+(r.owner?'<small>'+esc(r.owner)+'</small>':'')+'<small>'+esc(r.basis)+'</small>'+(r.source?'<small>Excel: '+esc(r.source)+'</small>':'')+(r.note?'<small>'+esc(r.note)+'</small>':'')+'</td><td>'+fmt(r.start)+'</td><td><b>'+fmt(r.date)+'</b></td><td>'+(r.days===null?'Plazo paralelo':r.days===0?'Mismo día':r.days+' día(s) hábil(es)')+'<br><span class="sc-tag '+(r.category==='Estimación interna'?'internal':r.actual?'actual':'')+'">'+esc(r.category)+'</span></td></tr>';}
html+='</tbody></table></div>';}
html+='<div class="sc-warning"><b>Condiciones del cálculo</b><ul><li>Los tiempos internos del Excel son estimaciones editables. Los plazos mínimos permiten fechas posteriores; los máximos permiten atención anterior.</li><li>El registro de participantes y las ramas de apelación tienen actividades paralelas; no se suman todas las filas para obtener una fecha.</li><li>Las fechas efectivas ingresadas sustituyen la proyección. Si existe postergación, suspensión o desierto, ajusta los hitos y el tipo de la nueva convocatoria.</li>'+result.warnings.map(w=>'<li>'+esc(w)+'</li>').join('')+'</ul></div>';$('scResult').innerHTML=html;answer();}catch(e){result=null;$('scResult').innerHTML='<p class="sc-error">'+esc(e.message)+'</p>';$('scAnswer').textContent='Revisa la fecha, el tipo y las condiciones para consultar el cronograma.';}}
function answer(){const q=$('scQuery').value.trim();if(!q){$('scAnswer').textContent='';return;}if(!result||result.unsupported){$('scAnswer').textContent='Selecciona un procedimiento cubierto por las plantillas para consultar sus fechas.';return;}
const hits=api.search(result,q);if(hits.length){$('scAnswer').innerHTML=hits.map(r=>'<article><h4>'+esc(r.label)+'</h4><p><b>'+fmt(r.date)+'</b> · '+(r.days===null?'Ventana paralela':r.days===0?'Mismo día':r.days+' día(s) hábil(es)')+' · '+esc(r.category)+'</p><p>'+esc(r.basis)+'</p>'+(r.source?'<p>Fuente: cronograma aportado, '+esc(r.source)+'.</p>':'')+'<p>Escenario: '+esc(api.types[result.type])+'; '+esc(api.stages[result.anchor])+' el '+fmt(result.start)+'.</p></article>').join('');return;}
const query=api.norm(q);let explanation='No encuentro esa actividad en el escenario calculado. Prueba con consultas, ofertas, consentimiento, requisitos, subsanación o firma.';
if(/SUBSAN|OBSERV/.test(query)&&!config().contractObservations)explanation='Para calcular la subsanación contractual activa “Con observaciones y subsanación”. El plazo máximo de subsanación es de 4 días hábiles desde el día siguiente de la notificación (art. 90.3).';
else if(/APEL/.test(query))explanation='Para consultar el trámite de apelación selecciona la rama ante la entidad o el TCP en “Condiciones del procedimiento”.';
else if(/ELEV|OECE/.test(query))explanation='Activa la elevación al OECE en las condiciones del LP/CP ordinario para calcular sus hitos.';
else if(/MERCADO|INDAG|REQUERIMIENTO|PREPARATOR/.test(query))explanation='Para ver las actividades previas a la convocatoria selecciona el hito “Inicio de actuaciones preparatorias” o “Inicio de programación / CMN”. Sus duraciones provienen del cronograma aportado.';
$('scAnswer').textContent=explanation;}
function applyRecord(id){populate();$('scRecord').value=id||'';const r=records().find(x=>String(x.id)===String(id));document.querySelectorAll('[data-sc-actual]').forEach(e=>e.value='');if(!r){$('scName').value='';$('scDate').value=peruToday();$('scAnchor').value='call';$('scType').value='cp';$('scRecordHint').textContent='Consulta libre: ingresa un hito y una fecha para generar una nueva contratación.';render();return;}
$('scType').value=api.inferType(r.procedimiento);$('scName').value=r.descripcion||'';const call=api.date(r.fechaConvocatoria);$('scAnchor').value=call?'call':'prep';$('scDate').value=call?api.iso(call):peruToday();
$('scRecordHint').textContent='Especialista: '+(r.especialista||'Sin asignar')+' · '+(r.procedimiento||'Sin tipo registrado')+'. '+(call?'Se utiliza la convocatoria registrada; verifica los hitos efectivos antes de calcular.':'Sin fecha de convocatoria registrada: se proyectan las actuaciones preparatorias desde hoy. Puedes cambiar la fecha.')+(r.fechaConsentimiento?' Consentimiento de referencia: '+r.fechaConsentimiento+'; confirma su registro efectivo en Pladicop.':'');render();}
function openRecord(id){for(const d of document.querySelectorAll('dialog[open]'))d.close();const nav=document.querySelector('[data-sun-route="simulador"]');if(nav)nav.click();else{document.body.dataset.sunPage='simulador';window.dispatchEvent(new CustomEvent('sunarp:pagechange',{detail:{page:'simulador'}}));const url=new URL(location.href);url.searchParams.set('pagina','simulador');history.replaceState(null,'',url);}
applyRecord(id);$('sunTimelineSimulator').scrollIntoView({behavior:'smooth',block:'start'});}
function injectLinks(){for(const b of document.querySelectorAll('[data-sun-open-new],[data-sun-proc-contract]')){const i=Number(b.dataset.sunOpenNew??b.dataset.sunProcContract);const r=records()[i];if(!r||!b.parentElement||b.parentElement.querySelector('[data-sc-record]'))continue;const el=document.createElement('button');el.type='button';el.className='sun-proc-linked';el.dataset.scRecord=String(r.id);el.textContent='📅 Consultar plazos';b.parentElement.appendChild(el);}}
$('scDate').value=peruToday();populate();render();
$('scRecord').addEventListener('change',()=>applyRecord($('scRecord').value));$('scRun').onclick=render;
$('sunTimelineSimulator').addEventListener('change',e=>{if(e.target.id!=='scRecord')render();});
$('scQueryForm').onsubmit=e=>{e.preventDefault();render();};document.addEventListener('click',e=>{const ex=e.target.closest('[data-sc-query]');if(ex){$('scQuery').value=ex.dataset.scQuery;render();}const link=e.target.closest('[data-sc-record]');if(link){e.preventDefault();openRecord(link.dataset.scRecord);}});
$('scPrint').onclick=()=>{render();if(result&&!result.unsupported)window.print();};
$('scCsv').onclick=()=>{render();if(!result||result.unsupported)return;const cfg=config(),rows=[['Objeto',$('scName').value],['Tipo',api.types[result.type]],['Hito',api.stages[cfg.anchor]],['Fecha base',cfg.date],[],['Fase','Actividad','Responsable','Inicio','Fin','Días hábiles','Carácter','Sustento','Referencia Excel'],...result.rows.map(r=>[r.phase,r.label,r.owner,fmt(r.start),fmt(r.date),r.days,r.category,r.basis,r.source])];const cell=v=>{let t=String(v??'');if(/^[=+@-]/.test(t))t="'"+t;return '"'+t.replace(/"/g,'""')+'"';};const blob=new Blob(['\uFEFF'+rows.map(r=>r.map(cell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='cronograma_sunarp_'+cfg.date+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);};
let queued=false;const scheduleLinks=()=>{if(queued)return;queued=true;requestAnimationFrame(()=>{queued=false;injectLinks();});};
for(const id of ['pacVisualNuevo','sunProcedures2026Panel']){const p=$(id);if(p)new MutationObserver(scheduleLinks).observe(p,{childList:true,subtree:true});}
window.addEventListener('sunarp:pagechange',()=>{populate();scheduleLinks();});window.addEventListener('focus',populate);injectLinks();window.openSunSchedule2026=openRecord;
})();
